const sql = $json.text || $json.output || $json.response || "";

const cleanedSQL = sql
  .replace(/```sql/gi, "")
  .replace(/```/g, "")
  .trim();

const forbidden = /\b(INSERT|UPDATE|DELETE|DROP|TRUNCATE|ALTER|CREATE|GRANT|REVOKE)\b/i;

if (forbidden.test(cleanedSQL)) {
  return [{
    json: {
      safe: false,
      error: "Unsafe SQL query blocked.",
      sql: cleanedSQL
    }
  }];
}

if (!/^SELECT\b/i.test(cleanedSQL)) {
  return [{
    json: {
      safe: false,
      error: "Only SELECT queries are allowed.",
      sql: cleanedSQL
    }
  }];
}

return [{
  json: {
    safe: true,
    sql: cleanedSQL
  }
}];
